        "required": ["flow", "source", "target", "topics"],
        "properties": {
          "flow": {"type": "string"},
          "source": {"enum": ["redpanda", "kafka"]},
          "target": {"enum": ["redpanda", "kafka"]},
          "topics": {"type": "array", "items": {"type": "string"}}
        }
      }
    }
